//! ♻️ The actual changed-path producer transfers admitted keys only after complete original key equality.
use super::*;
use crate::{list::persistent::{PersistentList,PersistentSet},named_edit::PersistentRankedKeys,retained_clone::{RetainedCloneRef,RetainedCloneSource,RETAINED_CLONE_BULK_PAGE_BYTES}};
/// 🪡️ Private production and original issuance prevent an arbitrary root from borrowing an admitted directory.
pub struct KeyPreservingPersistentSet<T:RetireOwned+Send+Sync+'static>{index:Option<Box<AdmittedNamedKeyIndex>>,set:Option<Box<PersistentSet<T>>>,authored:Option<RetainedCloneBinding>,candidate:ManuallyDrop<Option<PersistentList<T>>>,source:Option<Box<RetainedCloneSource<PersistentList<T>>>>,retirement:RetainedCloneClose,key:fn(&T)->&str,rank:usize,offset:usize,phase:u8,refused:bool,closing:bool}
impl<T:RetireOwned+Send+Sync+'static> KeyPreservingPersistentSet<T>{
 pub fn constructor_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()*2+size_of::<AdmittedNamedKeyIndex>()*2,capacity_bytes:size_of::<AdmittedNamedKeyIndex>(),depth:1,..Default::default()}}
 pub fn new(rank:usize,key:fn(&T)->&str,index:&mut Option<AdmittedNamedKeyIndex>,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,ValueError>{let d=Self::constructor_demand();if !retained_clone_grant_admits(grant,d){return Ok(None);}let owned=index.as_ref().ok_or_else(invalid)?;if !owned.ready()||rank>=owned.len||owned.projection!=key as usize{return Err(invalid());}Ok(Some((Self{index:Some(Box::new(index.take().ok_or_else(invalid)?)),set:None,authored:None,candidate:ManuallyDrop::new(None),source:None,retirement:Default::default(),key,rank,offset:0,phase:0,refused:false,closing:false},RetainedCloneProgress{retained_capacity_bytes:d.capacity_bytes,..paid(d)})))}
 fn validate(&self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>)->Result<(),ValueError>{if self.closing||self.refused||self.phase>7{return Err(invalid());}if self.phase<=4{self.index.as_ref().ok_or_else(invalid)?.check_source(&PersistentRankedKeys{original,key:self.key})?;}if self.authored.is_some()&&!authored.check_binding(&self.authored)?{return Err(invalid());}Ok(())}
 fn key_overhead(&self,original:RetainedCloneRef<'_,PersistentList<T>>)->Result<RetirementDemand,ValueError>{let mut d=PersistentRankedKeys{original,key:self.key}.rank_demand(self.rank)?;d.copy_bytes=d.copy_bytes.checked_add(size_of::<RetainedCloneRef<'_,str>>()*2+size_of::<SealedShared<T>>()+size_of::<usize>()*6).ok_or_else(invalid)?;Ok(d)}
 fn key_page(&self,overhead:usize,body:usize)->usize{(body.saturating_sub(overhead)/2).max(1).min(RETAINED_CLONE_BULK_PAGE_BYTES/2)}
 pub fn demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>,body:usize)->Result<RetirementDemand,ValueError>{self.validate(original,authored)?;match self.phase{
  0=>Ok(fixed(authored.binding_copy_bytes())),
  1=>{let mut d=self.key_overhead(original)?;d.copy_bytes+=self.key_page(d.copy_bytes,body)*2;Ok(d)},
  2=>if let Some(set)=self.set.as_ref(){set.demand(original,authored)}else{Ok(RetirementDemand{copy_bytes:size_of::<PersistentSet<T>>()*2+size_of::<Option<Box<PersistentSet<T>>>>()*2,capacity_bytes:size_of::<PersistentSet<T>>(),depth:1,..Default::default()})},
  3=>self.set.as_ref().ok_or_else(invalid)?.take_demand(),
  4=>{let birth=RetainedCloneSource::<PersistentList<T>>::owned_constructor_demand::<()>();Ok(RetirementDemand{copy_bytes:RetainedCloneSource::<PersistentList<T>>::constructor_copy_bytes()+size_of::<PersistentList<T>>()*2+size_of::<RetainedCloneSource<PersistentList<T>>>()*2,capacity_bytes:birth.capacity_bytes+size_of::<RetainedCloneSource<PersistentList<T>>>(),depth:birth.depth,..Default::default()})},
  5=>RetainedCloneBinding::close_demand(&self.index.as_ref().ok_or_else(invalid)?.original,body),
  6=>Ok(fixed(self.source.as_ref().ok_or_else(invalid)?.borrow().binding_copy_bytes()+size_of::<AdmittedNamedKeyIndex>())),
  7=>Ok(Default::default()),_=>Err(invalid())
 }}
 pub fn advance(&mut self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(original,authored,grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=paid(d);match self.phase{
  0=>{authored.bind(&mut self.authored,grant)?.ok_or_else(invalid)?;self.phase=1;},
  1=>{let source=PersistentRankedKeys{original,key:self.key};let(left,_)=source.observe_key(self.rank,grant)?.ok_or_else(invalid)?;let right=authored.project(self.key as usize,|row|(self.key)(row.get()));let left=left.get().as_bytes();let right=right.get().as_bytes();let overhead=self.key_overhead(original)?.copy_bytes;let count=self.key_page(overhead,grant.maximum_copy_bytes).min(left.len().saturating_sub(self.offset));p.copied_bytes=overhead+count*2;if left.len()!=right.len(){self.refused=true;}else{let end=self.offset.checked_add(count).ok_or_else(invalid)?;for i in self.offset..end{if left[i]!=right[i]{self.refused=true;break;}}self.offset=end;if !self.refused&&end==left.len(){self.phase=2;}}if self.refused{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"immutable named replacement changes its original key").with_retained_progress(p));}},
  2=>{if let Some(set)=self.set.as_mut(){let step=set.advance(original,authored,grant)?;p=step.progress();if set.output_ready(){self.phase=3;}}else{self.set=Some(Box::new(PersistentSet::new(self.rank)));p.retained_capacity_bytes=d.capacity_bytes;}},
  3=>{let(root,receipt)=self.set.as_mut().ok_or_else(invalid)?.take(grant)?.ok_or_else(invalid)?;*self.candidate=Some(root);p=receipt;self.phase=4;},
  4=>{let root=self.candidate.take().ok_or_else(invalid)?;match RetainedCloneSource::admit_owned(root,(),grant){Ok((source,receipt))=>{self.source=Some(Box::new(source));p.retained_capacity_bytes=receipt.retained_capacity_bytes+size_of::<RetainedCloneSource<PersistentList<T>>>();self.phase=5;},Err((e,root,()))=>{*self.candidate=Some(root);return Err(e);}}},
  5=>{let index=self.index.as_mut().ok_or_else(invalid)?;if index.original.is_some(){p=RetainedCloneBinding::close_one(&mut index.original,grant)?.progress();}if index.original.is_none(){self.phase=6;}},
  6=>{self.source.as_ref().ok_or_else(invalid)?.borrow().bind(&mut self.index.as_mut().ok_or_else(invalid)?.original,grant)?.ok_or_else(invalid)?;self.phase=7;},
  7=>return Ok(RetainedCloneStep::Complete(Default::default())),_=>return Err(invalid()),
 }Ok(if self.output_ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn refused(&self)->bool{self.refused}
 pub fn output_ready(&self)->bool{!self.closing&&!self.refused&&self.phase==7&&self.source.is_some()&&self.index.as_ref().is_some_and(|index|index.ready())}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(RetirementDemand{copy_bytes:size_of::<RetainedCloneSource<PersistentList<T>>>()*2+size_of::<AdmittedNamedKeyIndex>()*2+size_of::<u8>(),release_bytes:size_of::<RetainedCloneSource<PersistentList<T>>>()+size_of::<AdmittedNamedKeyIndex>(),depth:1,..Default::default()})}
 pub fn take(&mut self,grant:RetainedCloneGrant)->Result<Option<((RetainedCloneSource<PersistentList<T>>,AdmittedNamedKeyIndex),RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(grant,d){return Ok(None);}self.phase=8;Ok(Some(((*self.source.take().ok_or_else(invalid)?,*self.index.take().ok_or_else(invalid)?),RetainedCloneProgress{released_bytes:d.release_bytes,..paid(d)})))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(set)=self.set.as_mut(){set.begin_close();}if let Some(index)=self.index.as_mut(){index.begin_close();}}
 fn boxed_release<TBox>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<TBox>>>()*2,release_bytes:size_of::<TBox>(),depth:1,..Default::default()}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if let Some(set)=self.set.as_ref(){return if set.terminal_is_empty(){Ok(Self::boxed_release::<PersistentSet<T>>())}else{set.close_demand(body)};}if let Some(index)=self.index.as_ref(){return if index.terminal_is_empty(){Ok(Self::boxed_release::<AdmittedNamedKeyIndex>())}else{index.close_demand(body)};}if !self.retirement.is_empty()||self.candidate.is_some(){return self.retirement.next_owner_demands::<PersistentList<T>>(self.candidate.is_some(),&None,body);}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(Self::boxed_release::<RetainedCloneSource<PersistentList<T>>>())}else{source.next_close_demand(body)};}RetainedCloneBinding::close_demand(&self.authored,body)}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()));}let p=RetainedCloneProgress{released_bytes:d.release_bytes,..paid(d)};if let Some(set)=self.set.as_mut(){if set.terminal_is_empty(){self.set=None;return Ok(RetainedCloneStep::Progress(p));}return set.close_step(grant).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(index)=self.index.as_mut(){if index.terminal_is_empty(){self.index=None;return Ok(RetainedCloneStep::Progress(p));}return index.close_step(grant).map(|s|RetainedCloneStep::Progress(s.progress()));}if !self.retirement.is_empty(){return self.retirement.step_granted(grant).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.candidate,grant)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(source)=self.source.as_mut(){if source.terminal_is_empty(){self.source=None;return Ok(RetainedCloneStep::Progress(p));}return source.close_step(grant).map(|s|RetainedCloneStep::Progress(s.progress()));}RetainedCloneBinding::close_one(&mut self.authored,grant)}
 pub fn terminal_is_empty(&self)->bool{self.set.is_none()&&self.index.is_none()&&self.source.is_none()&&self.candidate.is_none()&&self.retirement.is_empty()&&self.authored.is_none()}
}
impl<T:RetireOwned+Send+Sync+'static> Drop for KeyPreservingPersistentSet<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"key-preserving producer retains original typed custody until funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.candidate);}}}}
